CREATE TABLE IF NOT EXISTS owner(id INTEGER PRIMARY KEY CHECK(id=1), email TEXT NOT NULL, salt TEXT NOT NULL, password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(ip TEXT PRIMARY KEY, count INTEGER NOT NULL, since REAL NOT NULL);
CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL UNIQUE, consent INTEGER NOT NULL, notes TEXT NOT NULL DEFAULT '', created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS grants(id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers, remaining INTEGER NOT NULL CHECK(remaining>=0), created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers, grant_id INTEGER REFERENCES grants, kind TEXT NOT NULL, cash INTEGER NOT NULL DEFAULT 0, delta INTEGER NOT NULL, balance INTEGER NOT NULL, details TEXT NOT NULL, created TEXT NOT NULL, original_id INTEGER REFERENCES events);
CREATE UNIQUE INDEX IF NOT EXISTS single_reversal ON events(original_id) WHERE kind='reversal';
CREATE TABLE IF NOT EXISTS requests(key TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, event_id INTEGER NOT NULL REFERENCES events);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, action TEXT NOT NULL, details TEXT NOT NULL, created TEXT NOT NULL);
